!function(e){function t(t){for(var a,i,o=t[0],m=t[1],d=t[2],s=0,g=[];s<o.length;s++)i=o[s],Object.prototype.hasOwnProperty.call(n,i)&&n[i]&&g.push(n[i][0]),n[i]=0;for(a in m)Object.prototype.hasOwnProperty.call(m,a)&&(e[a]=m[a]);for(c&&c(t);g.length;)g.shift()();return p.push.apply(p,d||[]),r()}function r(){for(var e,t=0;t<p.length;t++){for(var r,i=p[t],o=!0,m=1;m<i.length;m++)r=i[m],0!==n[r]&&(o=!1);o&&(p.splice(t--,1),e=a(a.s=i[0]))}return e}function a(t){if(i[t])return i[t].exports;var r=i[t]={i:t,l:!1,exports:{}};return e[t].call(r.exports,r,r.exports,a),r.l=!0,r.exports}var i={},n={13:0},p=[];a.m=e,a.c=i,a.d=function(e,t,r){a.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:r})},a.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},a.t=function(e,t){if(1&t&&(e=a(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(a.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var i in e)a.d(r,i,function(t){return e[t]}.bind(null,i));return r},a.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return a.d(t,"a",t),t},a.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},a.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=t,o=o.slice();for(var d=0;d<o.length;d++)t(o[d]);var c=m;p.push([84,0]),r()}({84:function(e,t,r){"use strict";r.r(t);var a=r(0);Object(a.a)("de","army",r(85),r(1))},85:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车辆","link":"de_army#de_army_avhtv"}],"model":"251/10型半履带装甲炮车<br>（37mm反坦克炮车）","description":"<p>251/10半履带装甲车是德军用251车体，安装了1门37mm反坦克炮，成为具有反坦克火力的中型装甲炮车。该型车已将车厢内两侧的座位拆除，以作弹药箱放置用，车内乘员由一名排级军官任车长，除驾驶员、通讯员外、还有2名炮手和1 名机枪射手。</p><p>251/10半履带装甲炮车主要作用是在战场上为德军进攻提供反坦克火力，也是一种火力支援装甲车。但从1943年开始，面对战场上大量出现的苏军中型坦克，37mm炮已显得无能为力，由此251/10在战场上逐渐失去了反坦克功能，只能用于对付对手的装甲车，其后被德军逐步淘汰，或换装了更大威力的反坦克炮。</p>","part1title":"","part1description":"","part1content":[{"image":"{{text}}炮车四视图{{image}}imgs/de/army/de_army_avhtv25110_11.jpg","description":"<h6>251/10中型半履带装甲炮车<br>（Sd Kfz 251/10）</h6><p>251/10中型半履带装甲炮车安装有1门Pak 35/36 37mm反坦克炮（备弹168发）和1挺MG34或MG42型后置高射机枪（备弹1100发）。该型车全重8吨，核载乘员6人，车长为指挥员，由排级军官担任、还有1名驾驶员、1 名通讯员和三名士兵，士兵中有2人操纵火炮（1人作为炮手负责瞄准，另1名负责弹药装填），而另1名士兵则负责后置高射机枪的射击。</p><p>该型炮车用251车体改装，所用车体包括A、B、C、D四种型号；1940年初，第一批251/10半履带装甲炮车下发部队使用，成为二战初期德军的一种重要的反坦克装备。</p><p>早期生产的251/10装甲炮车的火炮是安装大防盾，1941年后改用小防盾，而到了1943年底则完全取消了防盾。</p>","caption":""}],"part2title":"战场上的251/10半履带装甲炮车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_avhtv25110_21.jpg","description":"1942年1月，非洲战场利比亚，隶属德军第21装甲师104团的一辆251/10中型半履带装甲炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_22.jpg","description":"1942年9月，非洲战场埃及地区，一辆不明单位的德军251/10中型半履带装甲炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_23.jpg","description":"1943年，东线苏联战场，一辆不明单位的德军251/10中型半履带装甲炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_24.jpg","description":"1944年夏天，东线战场波兰，隶属德国武装党卫军第5“维京”装甲师第9党卫军反坦克团的一辆251/10中型半履带装甲炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_25.jpg","description":"1941年夏天，东线战场，向前线进发的一队德军251/10中型半履带装甲炮车正在苏联某村庄停下休息。最前面一辆车是使用B型车体改装，火炮采用中期的低矮型防盾，防盾正面与两侧加装了防护装甲钢板。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_26.jpg","description":"1941年夏天，东线苏联战场，一辆德军251/10中型半履带装甲炮车正在涉水行进。该车是使用早期的A型车体改装，火炮也是采用中期的低矮型防盾，防盾正面与两侧也加装了防护装甲钢板。在251/10半履带装甲炮车中，用这种低矮全正面防盾的炮车数量并不多，它属于从早期大防盾向小防盾的一种过渡。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_27.jpg","description":"1942年6月，东线苏联南部战场，一辆向斯大林格勒挺进的德军251/10中型半履带装甲炮车正停下检查。旁边是一辆Sdkfz 6自行高射炮车，车上装有37mm高射炮，为行进的车队提供防空保护。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_28.jpg","description":"1942年夏天，东线苏联战场，一辆德军251/10中型半履带装甲炮车正在用37mm火炮为德军的进攻提供火力支援。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_29.jpg","description":"1942年冬天，东线苏联战场，一辆德军251/10中型半履带装甲炮车正在执行战场侦察任务。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_30.jpg","description":"1944年6月，东线苏联战场白俄罗斯地区，被苏军击毁的一辆德军251/10中型半履带装甲炮车（C型车体）。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_31.jpg","description":"1944年春天，东线苏联战场，一辆正在行进中的德军251/10中型半履带装甲炮车（C型车体），车上还载有一名级别较高的德军军官。车左后侧是一辆被德军击毁的苏军美制M4A2型谢尔曼坦克（美国援助苏联）。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_32.jpg","description":"1944年秋天，东线苏联战场，正在抵挡苏军反攻的一辆德军251/10中型半履带装甲炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_33.jpg","description":"这是3张正在执行战斗任务的德军251/10中型半履带装甲炮车炮组乘员战斗的图片。","caption":""},{"image":"imgs/de/army/de_army_avhtv25110_34.jpg","description":"1942年，非洲战场，一辆被英军缴获的德军251/10中型半履带装甲炮车，车上一英军正在检查炮车上的37mm火炮。","caption":""}]}')}});